import { HttpMethod } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '../logger/app-logger';
import { MaterialResponseDTO } from './dtos/material.response.dto';
import { RequestHeadersDto } from './dtos/request.headers.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class MasterApi {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async fetchEwmMaterial(
    sapServers: Array<string>,
  ): Promise<Record<number, Array<string>>> {
    const context: JobsLogContext = {
      method: 'fetchEwmMaterial',
      service: 'MasterApi',
    };
    const serviceAppId = this.daprConfigService.masterApiAppId;
    const serviceMethodSeqnum = `material/GetEwmMaterialList`;
    const headersDto = new RequestHeadersDto('application/json');
    const token = `Bearer ${process.env.TOKEN}`;
    const options = {
      headers: {
        ...headersDto,
        authorization: token,
      },
    };
    const plantArray = Array.isArray(sapServers) ? sapServers : [sapServers];

    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethodSeqnum,
        HttpMethod.POST,
        plantArray,
        options,
      );
      // Return the valid response
      return response as Record<number, Array<string>>;
    } catch (error) {
      this.customLogger.error(
        `Error in fetch Ewm Material by plants [ ${sapServers} ]: ${error.message}`,
        context,
        error.stack,
      );
      return [];
    }
  }

  public async getSapServerByPlant(
    plant: number | Array<number>,
  ): Promise<{ sapServer: string | Array<string> }> {
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `/plant/getSapServerByPlant/${plant}`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.GET,
      undefined,
      options,
    );
    if (response) {
      return response as { sapServer: string };
    }
    throw new Error('Invalid response from getSapServerByPlant');
  }

  public async getEwmMaterialsByPlants(
    plants: Array<number>,
  ): Promise<Record<number, Array<string>>> {
    const context = {
      method: 'getEwmMaterialsByPlants',
      service: 'EwmGateway',
    };

    try {
      // Step 1: Get SAP servers for all plants (1:1 mapping)
      const sapServers = await this.getSapServerByPlant(plants); // Returns string[] matching plants[]

      const serverList: Array<string> = Array.isArray(sapServers.sapServer)
        ? sapServers.sapServer
        : [sapServers.sapServer];

      // Step 2: Fetch materials per server
      const materialsByServer: Record<
        string,
        Array<string>
      > = await this.fetchEwmMaterial(serverList);

      // Step 3: Map each plant to its server's materials
      const result: Record<number, Array<string>> = {};

      for (const [index, plant] of plants.entries()) {
        const server = serverList[index];
        result[plant] = server ? (materialsByServer[server] ?? []) : [];
      }

      return result;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving EWM materials for plants [${plants.join(', ')}]: ${error.message}`,
        context,
        error.stack,
      );
      return {};
    }
  }

  public async fetchEwmStorageLocations(
    plantList: Array<number>,
  ): Promise<Record<number, Array<string>>> {
    const context: JobsLogContext = {
      method: 'fetchEwmStorageLocations',
      service: 'MasterApi',
    };
    const token = `Bearer ${process.env.TOKEN}`;
    const serviceAppId = this.daprConfigService.masterApiAppId;
    const serviceMethodSeqnum = `/storage-location/GetEwmStorageLocationList`;
    const headersDto = new RequestHeadersDto('application/json');
    const options = {
      headers: {
        ...headersDto,
        authorization: token,
      },
    };
    const plantArray = Array.isArray(plantList) ? plantList : [plantList];

    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethodSeqnum,
        HttpMethod.POST,
        plantArray,
        options,
      );
      // Return the valid response
      return response as Record<number, Array<string>>;
    } catch (error) {
      this.customLogger.error(
        `Error in fetch Ewm Storage Locations by plants [ ${plantList} ]: ${error.message}`,
        context,
        error.stack,
      );
      return [];
    }
  }

  public async fetchMaterialByMaterialIdAndPlant(
    materialId: string,
    plant: number,
  ): Promise<string> {
    const context: JobsLogContext = {
      method: 'fetchMaterialByMaterialIdAndPlant',
      service: 'MasterApi',
    };
    const serviceAppId = this.daprConfigService.masterApiAppId;
    const serviceMethodSeqnum = `/material-dtl/getMaterialDtlById/${plant}/${materialId}`;
    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethodSeqnum,
        HttpMethod.GET,
      );
      // Return the valid response
      const materialResponse = response as MaterialResponseDTO;
      return materialResponse.autoTransfer;
    } catch (error) {
      this.customLogger.error(
        `Error in fetch material details [ ${plant}, ${materialId}]: ${error.message}`,
        context,
        error.stack,
      );
      return '';
    }
  }
}

