@Injectable()
export class SendEventService {
  private readonly daprClient: DaprClient;

  private readonly eventhubService: EventhubService;

  public constructor(
    eventhubService: EventhubService,
    private readonly masterApi: MasterApi,
    private readonly customLogger: AppLogger,
  ) {
    this.eventhubService = eventhubService;
    this.daprClient = new DaprClient({
      communicationProtocol: CommunicationProtocolEnum.HTTP,
      daprPort: process.env.DAPR_PORT,
    });
  }

  public async sendEventContainer(
    eventType: string,
    payload: ContainerDto,
  ): Promise<void> {
    const { outputBindingsEwmEvents } = this.eventhubService;

    const dataInput = {
      containerId: payload.containerId,
      currentStorageLocation: payload.storageLocation,
      flow: 'WIP',
      material: payload.material,
      packagingMaterial: payload.packagingMaterial,
      plant: Number(payload.plant),
      quantity: payload.quantity,
      unit: payload.unit,
      workCenter: payload.workcenter,
    };

    const event = new EventsContainerHistory(eventType, new Date(), dataInput);
    await this.daprClient.binding.send(
      outputBindingsEwmEvents,
      'create',
      event,
    );
  }

  public async sendEventTransfer(
    eventType: string,
    payload: TransferLogDto,
    pokaYoke: string,
  ): Promise<void> {
    const { outputBindingsEwmEvents } = this.eventhubService;
    const autoTransfer = await this.masterApi.fetchMaterialByMaterialIdAndPlant(
      payload.material,
      payload.plant,
    );
    let flowTypeAssign = '';
    if (autoTransfer === '1' && pokaYoke === 'API_P') {
      flowTypeAssign = 'SEQ';
    }

    const dataInput = {
      dateTime: formatDateToCompactUTC(payload.createdAt),
      flowType: flowTypeAssign,
      material: payload.material,
      plant: Number(payload.plant),
      quantity: payload.quantity,
      unit: payload.unit,
      workCenter: payload.workCenter,
    };
    const event = new EventsTransferHistory(eventType, new Date(), dataInput);
    await this.daprClient.binding.send(
      outputBindingsEwmEvents,
      'create',
      event,
    );
  }

  public async sendEventEkanbanTemp(
    eventType: string,
    payload: EkanbanTemporaryDto,
  ): Promise<void> {
    const { outputBindingsEwmEvents } = this.eventhubService;
    const timestamp = new Date();
    const dataInput = {
      dateTime: formatDateToCompactUTC(timestamp),
      material: payload.material,
      plant: Number(payload.plant),
      quantity: payload.quantity,
      unit: payload.unit,
      workCenter: payload.workCenter,
    };

    const event = new EkanbanTemporaryHistory(eventType, new Date(), dataInput);
    await this.daprClient.binding.send(
      outputBindingsEwmEvents,
      'create',
      event,
    );
  }
}

