import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class DaprConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get bindingContainer(): string {
    return this.configService.get<string>('bindingContainer') ?? '';
  }

  public get bindingTransferLog(): string {
    return this.configService.get<string>('bindingTransferLog') ?? '';
  }

  public get bindingEkanbanTemp(): string {
    return this.configService.get<string>('bindingEkanbanTemp') ?? '';
  }

  public get plantHierarchyApiAppId(): string {
    return this.configService.get<string>('plantHierarchyApiAppId') ?? '';
  }

  public get masterApiAppId(): string {
    return this.configService.get<string>('masterApiAppId') ?? '';
  }

  public onModuleInit(): void {
    this.validateConfiguration();
  }

  private validateConfiguration(): void {
    const context: JobsLogContext = {
      method: 'validateConfiguration',
      service: 'DaprConfigService',
    };
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'bindingContainer', value: this.bindingContainer },
      { key: 'plantHierarchyApiAppId', value: this.plantHierarchyApiAppId },
      { key: 'bindingTransferLog', value: this.bindingTransferLog },
      { key: 'bindingEkanbanTemp', value: this.bindingEkanbanTemp },
      { key: 'masterApiAppId', value: this.masterApiAppId },
    ];

    const missingConfigs = requiredConfigs.filter(
      (config) => config.value === undefined,
    );

    if (missingConfigs.length > 0) {
      for (const config of missingConfigs) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
      }
      throw new Error(
        'Configuration error: Some required configurations are not set.',
      );
    }
  }
}

/**
 * Common configuration settings shared across all EventHub topics
 */
interface EventHubCommonConfig {
  useEventhubSDK: boolean | undefined;
}

/**
 * Configuration for a specific EventHub topic
 */
interface EventHubTopicConfig {
  checkpointContainerName: string | undefined;
  checkpointInterval: number | undefined;
  consumerGroup: string | undefined;
  eventHubName: string | undefined;
  eventHubNamespace: string | undefined;
  storageAccountName: string | undefined;
}

/**
 * Complete EventHub configuration with common settings and topic-specific settings
 */
interface EventHubSdkConfig {
  eventHub: {
    common: EventHubCommonConfig;
    topics: {
      container: EventHubTopicConfig;
      transfer: EventHubTopicConfig;
    };
  };
}

export const eventHubSdkConfig = (): EventHubSdkConfig => ({
  eventHub: {
    common: {
      useEventhubSDK: process.env.EWM_GATEWAY_USE_EVENTHUB_SDK
        ? process.env.EWM_GATEWAY_USE_EVENTHUB_SDK === 'true'
        : undefined,
    },
    topics: {
      container: {
        checkpointContainerName:
          process.env.EVENTHUB_HU_DTL_CONTENT_CHECKPOINT_CONTAINER ?? '',

        checkpointInterval: Number(
          process.env.EVENTHUB_HU_DTL_CONTENT_CHECKPOINT_INTERVAL ?? '30000',
        ),

        consumerGroup: process.env.EVENTHUB_HU_DTL_CONTENT_CONSUMER_GROUP ?? '',

        eventHubName: process.env.EVENTHUB_HU_DTL_CONTENT_NAME ?? '',

        eventHubNamespace: process.env.EVENTHUB_HU_DTL_CONTENT_NAMESPACE,
        storageAccountName:
          process.env.EVENTHUB_HU_DTL_CONTENT_STORAGE_ACCOUNT_NAME,
      }, // Future topics will be added here
      transfer: {
        checkpointContainerName:
          process.env.EVENTHUB_TRANSFER_CHECKPOINT_CONTAINER ?? '',

        checkpointInterval: Number(
          process.env.EVENTHUB_TRANSFER_CHECKPOINT_INTERVAL ?? '30000',
        ),

        consumerGroup: process.env.EVENTHUB_TRANSFER_CONSUMER_GROUP ?? '',

        eventHubName: process.env.EVENTHUB_TRANSFER_NAME ?? '',

        eventHubNamespace: process.env.EVENTHUB_TRANSFER_NAMESPACE,
        storageAccountName: process.env.EVENTHUB_TRANSFER_STORAGE_ACCOUNT_NAME,
      }, // Future topics will be added here
    },
  },
});

