  eventHubNamespace: string;
  eventHubName: string;
  consumerGroup: string;
  storageAccountName: string;
  checkpointContainerName: string;
  checkpointInterval?: number;
}

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
