@Module({
  exports: [EventhubSdkConfigService],
  imports: [ConfigModule, AppConfigModule],
  providers: [EventhubSdkConfigService],
})
export class EventhubSdkConfigModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppConfigService } from '../app-config/app-config.service';
import { AppLogger } from '@/common/logger/app-logger';
import { EventHubSdkConfig } from '@/config/eventhub-sdk/eventhub-sdk-config.interface';

@Injectable()
export class EventhubSdkConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
    private readonly appConfigService: AppConfigService,
  ) {}

  // Common config getters
  public async useEventhubSDK(): Promise<boolean> {
    let value = this.configService.get<boolean>(
      'eventHub.common.useEventhubSDK',
    );
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'EventhubSdkConfigService',
    };
    if (value === undefined) {
      const configValue = await this.appConfigService.getConfigurationValue(
        'EWM_GATEWAY_USE_EVENTHUB_SDK',
      );
      value = configValue === 'true';
    } else {
      this.customLogger.verbose(
        `'useEventhubSDK' was read from environment variable`,
        context,
      );
    }

    return value ?? false;
  }

  // Containers topic config getters

  public get containerEventHubName(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.container.eventHubName',
      ) ?? ''
    );
  }

  public get containerEventHubNamespace(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.container.eventHubNamespace',
      ) ?? ''
    );
  }

  public get containerConsumerGroup(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.container.consumerGroup',
      ) ?? ''
    );
  }

  public get containerStorageAccountName(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.container.storageAccountName',
      ) ?? ''
    );
  }

  public get containerCheckpointContainerName(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.container.checkpointContainerName',
      ) ?? ''
    );
  }

  public get containerCheckpointInterval(): number {
    return (
      this.configService.get<number>(
        'eventHub.topics.container.checkpointInterval',
      ) ?? 30_000
    );
  }

  // Transfer topic config getters

  public get transferEventHubName(): string {
    return (
      this.configService.get<string>('eventHub.topics.transfer.eventHubName') ??
      ''
    );
  }

  public get transferEventHubNamespace(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.transfer.eventHubNamespace',
      ) ?? ''
    );
  }

  public get transferConsumerGroup(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.transfer.consumerGroup',
      ) ?? ''
    );
  }

  public get transferStorageAccountName(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.transfer.storageAccountName',
      ) ?? ''
    );
  }

  public get transferCheckpointContainerName(): string {
    return (
      this.configService.get<string>(
        'eventHub.topics.transfer.checkpointContainerName',
      ) ?? ''
    );
  }

  public get transferCheckpointInterval(): number {
    return (
      this.configService.get<number>(
        'eventHub.topics.transfer.checkpointInterval',
      ) ?? 30_000
    );
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'EventhubSdkConfigService',
    };

    // Required configurations for managed identity authentication
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'containerEventHubName', value: this.containerEventHubName },
      {
        key: 'containerEventHubNamespace',
        value: this.containerEventHubNamespace,
      },
      {
        key: 'containerStorageAccountName',
        value: this.containerStorageAccountName,
      },
      {
        key: 'containerCheckpointInterval',
        value: this.containerCheckpointInterval,
      },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.debug(
      'All required configurations for direct Event Hub are properly set',
      context,
    );
  }

  /**
   * Get the complete configuration for container topic
   * @returns Configuration object with all settings for NonTrsTicket topic
   */
  public getContainerConfig(): EventHubSdkConfig {
    return {
      checkpointContainerName: this.containerCheckpointContainerName,
      checkpointInterval: this.containerCheckpointInterval,
      consumerGroup: this.containerConsumerGroup,
      eventHubName: this.containerEventHubName,
      eventHubNamespace: this.containerEventHubNamespace,
      storageAccountName: this.containerStorageAccountName,
    };
  }

  /**
   * Get the complete configuration for transfer topic
   * @returns Configuration object with all settings for transfer topic
   */
  public getTransferConfig(): EventHubSdkConfig {
    return {
      checkpointContainerName: this.transferCheckpointContainerName,
      checkpointInterval: this.transferCheckpointInterval,
      consumerGroup: this.transferConsumerGroup,
      eventHubName: this.transferEventHubName,
      eventHubNamespace: this.transferEventHubNamespace,
      storageAccountName: this.transferStorageAccountName,
    };
  }

  /**
   * Helper method to get full config for a specific topic
   * @param topicName Name of the topic to get config for
   * @returns Complete configuration for the specified topic
   */
  public getTopicConfig(
    topicName: string /* Add more topics as they're added */,
  ): EventHubSdkConfig & {
    checkpointInterval?: number;
    maxRetries?: number;
  } {
    if (topicName === 'container') {
      return this.getContainerConfig();
    }
    if (topicName === 'transfer') {
      return this.getTransferConfig();
    }

    throw new Error(`Configuration for topic ${topicName} not found`);
  }
}

